import { test, expect } from '@playwright/test';
import * as ui from '../support/ui';

test.setTimeout(240_000);
test.describe("claim lock", () => {
  test("claim lock", { tag: '@functionality' }, async ({ browser }) => {
    const sheet = ui.sheetId();
    const pg_uma = await ui.userPage(browser, "uma", sheet);
    await ui.setToday(pg_uma, "2026-03-10");
    expect(await ui.setRate(pg_uma, {"grade": "A", "pct": "10.00"})).toBe(true);
    const p_ada = ui.must(await ui.addPerson(pg_uma, {"name": "Ada", "grade": "A"}));
    expect(await ui.setRole(pg_uma, "wes", "viewer")).toBe(true);
    const c_ada_0 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "10.00"}));
    const c_ada_1 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "20.00"}));
    const c_ada_2 = ui.must(await ui.addClaim(pg_uma, p_ada, {"amount": "30.00"}));
    expect(await ui.claimAction(pg_uma, c_ada_1, "open")).toBe(true);
    const pg_wes = await ui.userPage(browser, "wes", sheet);
    expect(await ui.claimEditOpen(pg_wes, c_ada_2)).toBe(false);
    await ui.refresh(pg_uma);
    expect(await ui.claimEditOpen(pg_uma, c_ada_2)).toBe(true);
    await ui.claimEditCancel(pg_uma, c_ada_2);
    expect(await ui.claimEditOpen(pg_uma, c_ada_0)).toBe(true);
    expect(await ui.claimEditOpen(pg_uma, c_ada_1)).toBe(false);
    const pg_vic = await ui.userPage(browser, "vic", sheet);
    expect(await ui.claimEditOpen(pg_vic, c_ada_0)).toBe(false);
    expect(await ui.editClaim(pg_vic, c_ada_0, {"amount": "11.00"})).toBe(false);
    expect(await ui.editClaim(pg_vic, c_ada_1, {"amount": "21.00"})).toBe(false);
    await ui.refresh(pg_uma);
    expect(await ui.claimEditSave(pg_uma, c_ada_0, {"amount": "12.00"})).toBe(true);
    await ui.refresh(pg_vic);
    expect(await ui.editClaim(pg_vic, c_ada_0, {"amount": "13.00"})).toBe(true);
    await ui.refresh(pg_uma);
    expect(await ui.claimEditOpen(pg_uma, c_ada_0)).toBe(true);
    await ui.claimEditCancel(pg_uma, c_ada_0);
    await ui.refresh(pg_vic);
    expect(await ui.claimEditOpen(pg_vic, c_ada_0)).toBe(true);
    await ui.claimEditCancel(pg_vic, c_ada_0);
    await ui.refresh(pg_uma);
    expect(await ui.claimEditOpen(pg_uma, c_ada_0)).toBe(true);
    await ui.refresh(pg_vic);
    expect(await ui.claimEditOpen(pg_vic, c_ada_0)).toBe(false);
    await ui.refresh(pg_uma);
    await ui.setToday(pg_uma, "2026-03-11");
    await ui.refresh(pg_vic);
    expect(await ui.claimEditSave(pg_vic, c_ada_0, {"amount": "14.00"})).toBe(true);
    await ui.refresh(pg_vic);
    await expect(pg_vic.getByTestId("person-row-" + p_ada).getByTestId("person-claimed")).toHaveText("20.00");
    await expect(pg_vic.getByTestId("claim-row-" + c_ada_2).getByTestId("claim-amount")).toHaveText("30.00");
    await expect(pg_vic.getByTestId("claim-row-" + c_ada_2).getByTestId("claim-status")).toHaveText("DRAFT");
    await expect(pg_vic.getByTestId("claim-row-" + c_ada_1).getByTestId("claim-amount")).toHaveText("20.00");
    await expect(pg_vic.getByTestId("claim-row-" + c_ada_1).getByTestId("claim-status")).toHaveText("OPEN");
    await expect(pg_vic.getByTestId("claim-row-" + c_ada_0).getByTestId("claim-amount")).toHaveText("14.00");
